INSERT INTO "traducao" ("id", "idioma", "hash_origem", "texto") VALUES
  (gen_random_uuid()::text, 'en', 'f94716968ee98017', '. From there come the questionnaires in 37 languages, the handbook, the benchmark and the official analysis spreadsheets by Martin Schrepp, which this tool uses and exports. Ferramenta UEQ is not an official UEQ product and has no affiliation with the authors.'),
  (gen_random_uuid()::text, 'en', '6560c2d946651623', '. The UEQ-S is by Martin Schrepp, Andreas Hinderks and Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'en', 'b74b10187c47ba41', 'Source: the UEQ Handbook, the official list of UEQ-S items in each language and the official UEQ-S analysis spreadsheet, at'),
  (gen_random_uuid()::text, 'en', '11277cef9cd51029', 'Method: UEQ-S, the short version of the User Experience Questionnaire (Schrepp, Hinderks and Thomaschewski, 2017). Benchmark and calculation from the official UEQ-S analysis spreadsheet, at'),
  (gen_random_uuid()::text, 'en', '9c0dcc2a186d213d', 'Method: User Experience Questionnaire (Laugwitz, Held and Schrepp, 2008). Benchmark by Schrepp, Hinderks and Thomaschewski (2017) and calculation from the official analysis spreadsheet, at'),
  (gen_random_uuid()::text, 'en', 'b391ed244a83d62b', 'The UEQ and the UEQ-S are free and maintained by the authors on the official website'),
  (gen_random_uuid()::text, 'es', 'f94716968ee98017', '. De allí vienen los cuestionarios en 37 idiomas, el manual, el benchmark y las hojas oficiales de análisis, de Martin Schrepp, que la herramienta usa y exporta. Ferramenta UEQ no es un producto oficial del UEQ ni tiene vínculo con los autores.'),
  (gen_random_uuid()::text, 'es', '6560c2d946651623', '. El UEQ-S es de Martin Schrepp, Andreas Hinderks y Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'es', 'b74b10187c47ba41', 'Fuente: el manual del UEQ, la lista oficial de los ítems del UEQ-S en cada idioma y la hoja oficial de análisis del UEQ-S, en'),
  (gen_random_uuid()::text, 'es', '11277cef9cd51029', 'Método: UEQ-S, la versión corta del User Experience Questionnaire (Schrepp, Hinderks y Thomaschewski, 2017). Benchmark y cálculo de la hoja oficial de análisis del UEQ-S, en'),
  (gen_random_uuid()::text, 'es', '9c0dcc2a186d213d', 'Método: User Experience Questionnaire (Laugwitz, Held y Schrepp, 2008). Benchmark de Schrepp, Hinderks y Thomaschewski (2017) y cálculo de la hoja oficial de análisis, en'),
  (gen_random_uuid()::text, 'es', 'b391ed244a83d62b', 'El UEQ y el UEQ-S son gratuitos y los mantienen sus autores en el sitio oficial'),
  (gen_random_uuid()::text, 'de', 'f94716968ee98017', '. Von dort stammen die Fragebögen in 37 Sprachen, das Handbuch, der Benchmark und die offiziellen Auswertungstabellen von Martin Schrepp, die dieses Tool nutzt und exportiert. Ferramenta UEQ ist kein offizielles Produkt des UEQ und steht in keiner Verbindung zu den Autoren.'),
  (gen_random_uuid()::text, 'de', '6560c2d946651623', '. Der UEQ-S stammt von Martin Schrepp, Andreas Hinderks und Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'de', 'b74b10187c47ba41', 'Quelle: das UEQ-Handbuch, die offizielle Liste der UEQ-S-Items in jeder Sprache und die offizielle Auswertungstabelle des UEQ-S, auf'),
  (gen_random_uuid()::text, 'de', '11277cef9cd51029', 'Methode: UEQ-S, die Kurzversion des User Experience Questionnaire (Schrepp, Hinderks und Thomaschewski, 2017). Benchmark und Berechnung aus der offiziellen Auswertungstabelle des UEQ-S, auf'),
  (gen_random_uuid()::text, 'de', '9c0dcc2a186d213d', 'Methode: User Experience Questionnaire (Laugwitz, Held und Schrepp, 2008). Benchmark von Schrepp, Hinderks und Thomaschewski (2017) und Berechnung aus der offiziellen Auswertungstabelle, auf'),
  (gen_random_uuid()::text, 'de', 'b391ed244a83d62b', 'Der UEQ und der UEQ-S sind kostenlos und werden von den Autoren auf der offiziellen Website gepflegt:'),
  (gen_random_uuid()::text, 'fr', 'f94716968ee98017', '. De là viennent les questionnaires en 37 langues, le manuel, le benchmark et les feuilles officielles d''analyse de Martin Schrepp, que l''outil utilise et exporte. Ferramenta UEQ n''est pas un produit officiel de l''UEQ et n''a aucun lien avec les auteurs.'),
  (gen_random_uuid()::text, 'fr', '6560c2d946651623', '. L''UEQ-S est de Martin Schrepp, Andreas Hinderks et Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'fr', 'b74b10187c47ba41', 'Source : le manuel de l''UEQ, la liste officielle des items de l''UEQ-S dans chaque langue et la feuille officielle d''analyse de l''UEQ-S, sur'),
  (gen_random_uuid()::text, 'fr', '11277cef9cd51029', 'Méthode : UEQ-S, la version courte du User Experience Questionnaire (Schrepp, Hinderks et Thomaschewski, 2017). Benchmark et calcul de la feuille officielle d''analyse de l''UEQ-S, sur'),
  (gen_random_uuid()::text, 'fr', '9c0dcc2a186d213d', 'Méthode : User Experience Questionnaire (Laugwitz, Held et Schrepp, 2008). Benchmark de Schrepp, Hinderks et Thomaschewski (2017) et calcul de la feuille officielle d''analyse, sur'),
  (gen_random_uuid()::text, 'fr', 'b391ed244a83d62b', 'L''UEQ et l''UEQ-S sont gratuits et maintenus par leurs auteurs sur le site officiel'),
  (gen_random_uuid()::text, 'it', 'f94716968ee98017', '. Da lì provengono i questionari in 37 lingue, il manuale, il benchmark e i fogli ufficiali di analisi di Martin Schrepp, che lo strumento usa ed esporta. Ferramenta UEQ non è un prodotto ufficiale dell''UEQ e non ha legami con gli autori.'),
  (gen_random_uuid()::text, 'it', '6560c2d946651623', '. L''UEQ-S è di Martin Schrepp, Andreas Hinderks e Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'it', 'b74b10187c47ba41', 'Fonte: il manuale dell''UEQ, l''elenco ufficiale degli item dell''UEQ-S in ogni lingua e il foglio ufficiale di analisi dell''UEQ-S, su'),
  (gen_random_uuid()::text, 'it', '11277cef9cd51029', 'Metodo: UEQ-S, la versione breve dello User Experience Questionnaire (Schrepp, Hinderks e Thomaschewski, 2017). Benchmark e calcolo del foglio ufficiale di analisi dell''UEQ-S, su'),
  (gen_random_uuid()::text, 'it', '9c0dcc2a186d213d', 'Metodo: User Experience Questionnaire (Laugwitz, Held e Schrepp, 2008). Benchmark di Schrepp, Hinderks e Thomaschewski (2017) e calcolo del foglio ufficiale di analisi, su'),
  (gen_random_uuid()::text, 'it', 'b391ed244a83d62b', 'L''UEQ e l''UEQ-S sono gratuiti e mantenuti dagli autori sul sito ufficiale'),
  (gen_random_uuid()::text, 'nl', 'f94716968ee98017', '. Daar komen de vragenlijsten in 37 talen, het handboek, de benchmark en de officiële analysewerkbladen van Martin Schrepp vandaan, die deze tool gebruikt en exporteert. Ferramenta UEQ is geen officieel product van de UEQ en heeft geen band met de auteurs.'),
  (gen_random_uuid()::text, 'nl', '6560c2d946651623', '. De UEQ-S is van Martin Schrepp, Andreas Hinderks en Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'nl', 'b74b10187c47ba41', 'Bron: het UEQ-handboek, de officiële lijst van de UEQ-S-items in elke taal en het officiële analysewerkblad van de UEQ-S, op'),
  (gen_random_uuid()::text, 'nl', '11277cef9cd51029', 'Methode: UEQ-S, de korte versie van de User Experience Questionnaire (Schrepp, Hinderks en Thomaschewski, 2017). Benchmark en berekening uit het officiële analysewerkblad van de UEQ-S, op'),
  (gen_random_uuid()::text, 'nl', '9c0dcc2a186d213d', 'Methode: User Experience Questionnaire (Laugwitz, Held en Schrepp, 2008). Benchmark van Schrepp, Hinderks en Thomaschewski (2017) en berekening uit het officiële analysewerkblad, op'),
  (gen_random_uuid()::text, 'nl', 'b391ed244a83d62b', 'De UEQ en de UEQ-S zijn gratis en worden door de auteurs bijgehouden op de officiële website'),
  (gen_random_uuid()::text, 'da', 'f94716968ee98017', '. Derfra kommer spørgeskemaerne på 37 sprog, håndbogen, benchmarken og de officielle analyseregneark af Martin Schrepp, som værktøjet bruger og eksporterer. Ferramenta UEQ er ikke et officielt UEQ-produkt og har ingen tilknytning til forfatterne.'),
  (gen_random_uuid()::text, 'da', '6560c2d946651623', '. UEQ-S er udviklet af Martin Schrepp, Andreas Hinderks og Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'da', 'b74b10187c47ba41', 'Kilde: UEQ-håndbogen, den officielle liste over UEQ-S-items på hvert sprog og det officielle analyseregneark for UEQ-S, på'),
  (gen_random_uuid()::text, 'da', '11277cef9cd51029', 'Metode: UEQ-S, den korte version af User Experience Questionnaire (Schrepp, Hinderks og Thomaschewski, 2017). Benchmark og beregning fra det officielle analyseregneark for UEQ-S, på'),
  (gen_random_uuid()::text, 'da', '9c0dcc2a186d213d', 'Metode: User Experience Questionnaire (Laugwitz, Held og Schrepp, 2008). Benchmark af Schrepp, Hinderks og Thomaschewski (2017) og beregning fra det officielle analyseregneark, på'),
  (gen_random_uuid()::text, 'da', 'b391ed244a83d62b', 'UEQ og UEQ-S er gratis og vedligeholdes af forfatterne på det officielle websted'),
  (gen_random_uuid()::text, 'sv', 'f94716968ee98017', '. Därifrån kommer enkäterna på 37 språk, handboken, benchmarken och de officiella analysbladen av Martin Schrepp, som verktyget använder och exporterar. Ferramenta UEQ är ingen officiell UEQ-produkt och har ingen koppling till författarna.'),
  (gen_random_uuid()::text, 'sv', '6560c2d946651623', '. UEQ-S är framtagen av Martin Schrepp, Andreas Hinderks och Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'sv', 'b74b10187c47ba41', 'Källa: UEQ-handboken, den officiella listan över UEQ-S-items på varje språk och det officiella analysbladet för UEQ-S, på'),
  (gen_random_uuid()::text, 'sv', '11277cef9cd51029', 'Metod: UEQ-S, den korta versionen av User Experience Questionnaire (Schrepp, Hinderks och Thomaschewski, 2017). Benchmark och beräkning från det officiella analysbladet för UEQ-S, på'),
  (gen_random_uuid()::text, 'sv', '9c0dcc2a186d213d', 'Metod: User Experience Questionnaire (Laugwitz, Held och Schrepp, 2008). Benchmark av Schrepp, Hinderks och Thomaschewski (2017) och beräkning från det officiella analysbladet, på'),
  (gen_random_uuid()::text, 'sv', 'b391ed244a83d62b', 'UEQ och UEQ-S är gratis och underhålls av författarna på den officiella webbplatsen'),
  (gen_random_uuid()::text, 'nb', 'f94716968ee98017', '. Derfra kommer spørreskjemaene på 37 språk, håndboken, benchmarken og de offisielle analyseregnearkene av Martin Schrepp, som verktøyet bruker og eksporterer. Ferramenta UEQ er ikke et offisielt UEQ-produkt og har ingen tilknytning til forfatterne.'),
  (gen_random_uuid()::text, 'nb', '6560c2d946651623', '. UEQ-S er utviklet av Martin Schrepp, Andreas Hinderks og Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'nb', 'b74b10187c47ba41', 'Kilde: UEQ-håndboken, den offisielle listen over UEQ-S-itemene på hvert språk og det offisielle analyseregnearket for UEQ-S, på'),
  (gen_random_uuid()::text, 'nb', '11277cef9cd51029', 'Metode: UEQ-S, kortversjonen av User Experience Questionnaire (Schrepp, Hinderks og Thomaschewski, 2017). Benchmark og beregning fra det offisielle analyseregnearket for UEQ-S, på'),
  (gen_random_uuid()::text, 'nb', '9c0dcc2a186d213d', 'Metode: User Experience Questionnaire (Laugwitz, Held og Schrepp, 2008). Benchmark av Schrepp, Hinderks og Thomaschewski (2017) og beregning fra det offisielle analyseregnearket, på'),
  (gen_random_uuid()::text, 'nb', 'b391ed244a83d62b', 'UEQ og UEQ-S er gratis og vedlikeholdes av forfatterne på det offisielle nettstedet'),
  (gen_random_uuid()::text, 'fi', 'f94716968ee98017', '. Sieltä tulevat kyselyt 37 kielellä, käsikirja, benchmark ja Martin Schreppin viralliset analyysitaulukot, joita työkalu käyttää ja vie. Ferramenta UEQ ei ole UEQ:n virallinen tuote, eikä sillä ole yhteyttä tekijöihin.'),
  (gen_random_uuid()::text, 'fi', '6560c2d946651623', '. UEQ-S:n ovat laatineet Martin Schrepp, Andreas Hinderks ja Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'fi', 'b74b10187c47ba41', 'Lähde: UEQ:n käsikirja, UEQ-S:n osioiden virallinen luettelo kullakin kielellä ja UEQ-S:n virallinen analyysitaulukko, osoitteessa'),
  (gen_random_uuid()::text, 'fi', '11277cef9cd51029', 'Menetelmä: UEQ-S, User Experience Questionnairen lyhyt versio (Schrepp, Hinderks ja Thomaschewski, 2017). Benchmark ja laskenta UEQ-S:n virallisesta analyysitaulukosta, osoitteessa'),
  (gen_random_uuid()::text, 'fi', '9c0dcc2a186d213d', 'Menetelmä: User Experience Questionnaire (Laugwitz, Held ja Schrepp, 2008). Benchmark: Schrepp, Hinderks ja Thomaschewski (2017), laskenta virallisesta analyysitaulukosta, osoitteessa'),
  (gen_random_uuid()::text, 'fi', 'b391ed244a83d62b', 'UEQ ja UEQ-S ovat maksuttomia, ja tekijät ylläpitävät niitä virallisella sivustolla'),
  (gen_random_uuid()::text, 'et', 'f94716968ee98017', '. Sealt pärinevad küsimustikud 37 keeles, käsiraamat, benchmark ja Martin Schreppi ametlikud analüüsitabelid, mida tööriist kasutab ja ekspordib. Ferramenta UEQ ei ole UEQ ametlik toode ega ole autoritega seotud.'),
  (gen_random_uuid()::text, 'et', '6560c2d946651623', '. UEQ-S-i autorid on Martin Schrepp, Andreas Hinderks ja Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'et', 'b74b10187c47ba41', 'Allikas: UEQ käsiraamat, UEQ-S väidete ametlik loend igas keeles ja UEQ-S ametlik analüüsitabel, aadressil'),
  (gen_random_uuid()::text, 'et', '11277cef9cd51029', 'Meetod: UEQ-S, User Experience Questionnaire''i lühiversioon (Schrepp, Hinderks ja Thomaschewski, 2017). Benchmark ja arvutus UEQ-S ametlikust analüüsitabelist, aadressil'),
  (gen_random_uuid()::text, 'et', '9c0dcc2a186d213d', 'Meetod: User Experience Questionnaire (Laugwitz, Held ja Schrepp, 2008). Benchmark: Schrepp, Hinderks ja Thomaschewski (2017), arvutus ametlikust analüüsitabelist, aadressil'),
  (gen_random_uuid()::text, 'et', 'b391ed244a83d62b', 'UEQ ja UEQ-S on tasuta ning autorid hoiavad neid ametlikul veebisaidil'),
  (gen_random_uuid()::text, 'pl', 'f94716968ee98017', '. Stamtąd pochodzą kwestionariusze w 37 językach, podręcznik, benchmark i oficjalne arkusze analizy Martina Schreppa, których narzędzie używa i które eksportuje. Ferramenta UEQ nie jest oficjalnym produktem UEQ i nie jest powiązana z autorami.'),
  (gen_random_uuid()::text, 'pl', '6560c2d946651623', '. Autorami UEQ-S są Martin Schrepp, Andreas Hinderks i Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'pl', 'b74b10187c47ba41', 'Źródło: podręcznik UEQ, oficjalna lista pozycji UEQ-S w każdym języku i oficjalny arkusz analizy UEQ-S, na stronie'),
  (gen_random_uuid()::text, 'pl', '11277cef9cd51029', 'Metoda: UEQ-S, skrócona wersja User Experience Questionnaire (Schrepp, Hinderks i Thomaschewski, 2017). Benchmark i obliczenia z oficjalnego arkusza analizy UEQ-S, na stronie'),
  (gen_random_uuid()::text, 'pl', '9c0dcc2a186d213d', 'Metoda: User Experience Questionnaire (Laugwitz, Held i Schrepp, 2008). Benchmark: Schrepp, Hinderks i Thomaschewski (2017), obliczenia z oficjalnego arkusza analizy, na stronie'),
  (gen_random_uuid()::text, 'pl', 'b391ed244a83d62b', 'UEQ i UEQ-S są bezpłatne, a autorzy utrzymują je na oficjalnej stronie'),
  (gen_random_uuid()::text, 'cs', 'f94716968ee98017', '. Odtud pocházejí dotazníky ve 37 jazycích, příručka, benchmark a oficiální analytické tabulky Martina Schreppa, které nástroj používá a exportuje. Ferramenta UEQ není oficiální produkt UEQ a s autory není nijak spojena.'),
  (gen_random_uuid()::text, 'cs', '6560c2d946651623', '. Autory UEQ-S jsou Martin Schrepp, Andreas Hinderks a Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'cs', 'b74b10187c47ba41', 'Zdroj: příručka UEQ, oficiální seznam položek UEQ-S v každém jazyce a oficiální analytická tabulka UEQ-S, na'),
  (gen_random_uuid()::text, 'cs', '11277cef9cd51029', 'Metoda: UEQ-S, krátká verze User Experience Questionnaire (Schrepp, Hinderks a Thomaschewski, 2017). Benchmark a výpočet z oficiální analytické tabulky UEQ-S, na'),
  (gen_random_uuid()::text, 'cs', '9c0dcc2a186d213d', 'Metoda: User Experience Questionnaire (Laugwitz, Held a Schrepp, 2008). Benchmark: Schrepp, Hinderks a Thomaschewski (2017), výpočet z oficiální analytické tabulky, na'),
  (gen_random_uuid()::text, 'cs', 'b391ed244a83d62b', 'UEQ a UEQ-S jsou zdarma a autoři je udržují na oficiálním webu'),
  (gen_random_uuid()::text, 'sk', 'f94716968ee98017', '. Odtiaľ pochádzajú dotazníky v 37 jazykoch, príručka, benchmark a oficiálne analytické tabuľky Martina Schreppa, ktoré nástroj používa a exportuje. Ferramenta UEQ nie je oficiálny produkt UEQ a s autormi nie je nijako spojená.'),
  (gen_random_uuid()::text, 'sk', '6560c2d946651623', '. Autormi UEQ-S sú Martin Schrepp, Andreas Hinderks a Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'sk', 'b74b10187c47ba41', 'Zdroj: príručka UEQ, oficiálny zoznam položiek UEQ-S v každom jazyku a oficiálna analytická tabuľka UEQ-S, na'),
  (gen_random_uuid()::text, 'sk', '11277cef9cd51029', 'Metóda: UEQ-S, krátka verzia User Experience Questionnaire (Schrepp, Hinderks a Thomaschewski, 2017). Benchmark a výpočet z oficiálnej analytickej tabuľky UEQ-S, na'),
  (gen_random_uuid()::text, 'sk', '9c0dcc2a186d213d', 'Metóda: User Experience Questionnaire (Laugwitz, Held a Schrepp, 2008). Benchmark: Schrepp, Hinderks a Thomaschewski (2017), výpočet z oficiálnej analytickej tabuľky, na'),
  (gen_random_uuid()::text, 'sk', 'b391ed244a83d62b', 'UEQ a UEQ-S sú bezplatné a autori ich udržiavajú na oficiálnom webe'),
  (gen_random_uuid()::text, 'sl', 'f94716968ee98017', '. Od tam izvirajo vprašalniki v 37 jezikih, priročnik, primerjalna vrednost in uradne analitične preglednice Martina Schreppa, ki jih orodje uporablja in izvaža. Ferramenta UEQ ni uradni izdelek UEQ in ni povezana z avtorji.'),
  (gen_random_uuid()::text, 'sl', '6560c2d946651623', '. Avtorji UEQ-S so Martin Schrepp, Andreas Hinderks in Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'sl', 'b74b10187c47ba41', 'Vir: priročnik UEQ, uradni seznam postavk UEQ-S v vsakem jeziku in uradna analitična preglednica UEQ-S, na'),
  (gen_random_uuid()::text, 'sl', '11277cef9cd51029', 'Metoda: UEQ-S, kratka različica User Experience Questionnaire (Schrepp, Hinderks in Thomaschewski, 2017). Primerjalna vrednost in izračun iz uradne analitične preglednice UEQ-S, na'),
  (gen_random_uuid()::text, 'sl', '9c0dcc2a186d213d', 'Metoda: User Experience Questionnaire (Laugwitz, Held in Schrepp, 2008). Primerjalna vrednost: Schrepp, Hinderks in Thomaschewski (2017), izračun iz uradne analitične preglednice, na'),
  (gen_random_uuid()::text, 'sl', 'b391ed244a83d62b', 'UEQ in UEQ-S sta brezplačna, avtorji pa ju vzdržujejo na uradni spletni strani'),
  (gen_random_uuid()::text, 'hr', 'f94716968ee98017', '. Odatle dolaze upitnici na 37 jezika, priručnik, referentne vrijednosti i službene tablice za analizu Martina Schreppa, koje alat koristi i izvozi. Ferramenta UEQ nije službeni proizvod UEQ-a i nije povezana s autorima.'),
  (gen_random_uuid()::text, 'hr', '6560c2d946651623', '. Autori UEQ-S-a su Martin Schrepp, Andreas Hinderks i Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'hr', 'b74b10187c47ba41', 'Izvor: priručnik UEQ-a, službeni popis čestica UEQ-S-a na svakom jeziku i službena tablica za analizu UEQ-S-a, na'),
  (gen_random_uuid()::text, 'hr', '11277cef9cd51029', 'Metoda: UEQ-S, kratka verzija User Experience Questionnairea (Schrepp, Hinderks i Thomaschewski, 2017). Referentne vrijednosti i izračun iz službene tablice za analizu UEQ-S-a, na'),
  (gen_random_uuid()::text, 'hr', '9c0dcc2a186d213d', 'Metoda: User Experience Questionnaire (Laugwitz, Held i Schrepp, 2008). Referentne vrijednosti: Schrepp, Hinderks i Thomaschewski (2017), izračun iz službene tablice za analizu, na'),
  (gen_random_uuid()::text, 'hr', 'b391ed244a83d62b', 'UEQ i UEQ-S besplatni su i autori ih održavaju na službenoj stranici'),
  (gen_random_uuid()::text, 'bs', 'f94716968ee98017', '. Odatle dolaze upitnici na 37 jezika, priručnik, referentne vrijednosti i zvanične tabele za analizu Martina Schreppa, koje alat koristi i izvozi. Ferramenta UEQ nije zvanični proizvod UEQ-a i nije povezana s autorima.'),
  (gen_random_uuid()::text, 'bs', '6560c2d946651623', '. Autori UEQ-S-a su Martin Schrepp, Andreas Hinderks i Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'bs', 'b74b10187c47ba41', 'Izvor: priručnik UEQ-a, zvanični spisak stavki UEQ-S-a na svakom jeziku i zvanična tabela za analizu UEQ-S-a, na'),
  (gen_random_uuid()::text, 'bs', '11277cef9cd51029', 'Metoda: UEQ-S, kratka verzija User Experience Questionnairea (Schrepp, Hinderks i Thomaschewski, 2017). Referentne vrijednosti i izračun iz zvanične tabele za analizu UEQ-S-a, na'),
  (gen_random_uuid()::text, 'bs', '9c0dcc2a186d213d', 'Metoda: User Experience Questionnaire (Laugwitz, Held i Schrepp, 2008). Referentne vrijednosti: Schrepp, Hinderks i Thomaschewski (2017), izračun iz zvanične tabele za analizu, na'),
  (gen_random_uuid()::text, 'bs', 'b391ed244a83d62b', 'UEQ i UEQ-S su besplatni i autori ih održavaju na zvaničnoj stranici'),
  (gen_random_uuid()::text, 'hu', 'f94716968ee98017', '. Innen származnak a kérdőívek 37 nyelven, a kézikönyv, a benchmark és Martin Schrepp hivatalos elemző táblázatai, amelyeket az eszköz használ és exportál. A Ferramenta UEQ nem hivatalos UEQ-termék, és nem áll kapcsolatban a szerzőkkel.'),
  (gen_random_uuid()::text, 'hu', '6560c2d946651623', '. Az UEQ-S szerzői Martin Schrepp, Andreas Hinderks és Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'hu', 'b74b10187c47ba41', 'Forrás: az UEQ kézikönyve, az UEQ-S tételeinek hivatalos listája minden nyelven és az UEQ-S hivatalos elemző táblázata, itt:'),
  (gen_random_uuid()::text, 'hu', '11277cef9cd51029', 'Módszer: UEQ-S, a User Experience Questionnaire rövid változata (Schrepp, Hinderks és Thomaschewski, 2017). Benchmark és számítás az UEQ-S hivatalos elemző táblázatából, itt:'),
  (gen_random_uuid()::text, 'hu', '9c0dcc2a186d213d', 'Módszer: User Experience Questionnaire (Laugwitz, Held és Schrepp, 2008). Benchmark: Schrepp, Hinderks és Thomaschewski (2017), számítás a hivatalos elemző táblázatból, itt:'),
  (gen_random_uuid()::text, 'hu', 'b391ed244a83d62b', 'Az UEQ és az UEQ-S ingyenes, a szerzők a hivatalos weboldalon gondozzák:'),
  (gen_random_uuid()::text, 'bg', 'f94716968ee98017', '. Оттам идват въпросниците на 37 езика, наръчникът, бенчмаркът и официалните таблици за анализ на Martin Schrepp, които инструментът използва и експортира. Ferramenta UEQ не е официален продукт на UEQ и не е свързана с авторите.'),
  (gen_random_uuid()::text, 'bg', '6560c2d946651623', '. Автори на UEQ-S са Martin Schrepp, Andreas Hinderks и Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'bg', 'b74b10187c47ba41', 'Източник: наръчникът на UEQ, официалният списък на твърденията на UEQ-S на всеки език и официалната таблица за анализ на UEQ-S, на'),
  (gen_random_uuid()::text, 'bg', '11277cef9cd51029', 'Метод: UEQ-S, кратката версия на User Experience Questionnaire (Schrepp, Hinderks и Thomaschewski, 2017). Бенчмарк и изчисление от официалната таблица за анализ на UEQ-S, на'),
  (gen_random_uuid()::text, 'bg', '9c0dcc2a186d213d', 'Метод: User Experience Questionnaire (Laugwitz, Held и Schrepp, 2008). Бенчмарк от Schrepp, Hinderks и Thomaschewski (2017) и изчисление от официалната таблица за анализ, на'),
  (gen_random_uuid()::text, 'bg', 'b391ed244a83d62b', 'UEQ и UEQ-S са безплатни и се поддържат от авторите на официалния сайт'),
  (gen_random_uuid()::text, 'ru', 'f94716968ee98017', '. Оттуда — опросники на 37 языках, руководство, бенчмарк и официальные таблицы анализа Martin Schrepp, которые инструмент использует и экспортирует. Ferramenta UEQ не является официальным продуктом UEQ и не связана с авторами.'),
  (gen_random_uuid()::text, 'ru', '6560c2d946651623', '. Авторы UEQ-S — Martin Schrepp, Andreas Hinderks и Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'ru', 'b74b10187c47ba41', 'Источник: руководство UEQ, официальный список пунктов UEQ-S на каждом языке и официальная таблица анализа UEQ-S, на сайте'),
  (gen_random_uuid()::text, 'ru', '11277cef9cd51029', 'Метод: UEQ-S, краткая версия User Experience Questionnaire (Schrepp, Hinderks и Thomaschewski, 2017). Бенчмарк и расчёт по официальной таблице анализа UEQ-S, на сайте'),
  (gen_random_uuid()::text, 'ru', '9c0dcc2a186d213d', 'Метод: User Experience Questionnaire (Laugwitz, Held и Schrepp, 2008). Бенчмарк Schrepp, Hinderks и Thomaschewski (2017) и расчёт по официальной таблице анализа, на сайте'),
  (gen_random_uuid()::text, 'ru', 'b391ed244a83d62b', 'UEQ и UEQ-S бесплатны, авторы поддерживают их на официальном сайте'),
  (gen_random_uuid()::text, 'el', 'f94716968ee98017', '. Από εκεί προέρχονται τα ερωτηματολόγια σε 37 γλώσσες, το εγχειρίδιο, το benchmark και τα επίσημα φύλλα ανάλυσης του Martin Schrepp, που χρησιμοποιεί και εξάγει το εργαλείο. Το Ferramenta UEQ δεν είναι επίσημο προϊόν του UEQ και δεν συνδέεται με τους συγγραφείς.'),
  (gen_random_uuid()::text, 'el', '6560c2d946651623', '. Το UEQ-S είναι των Martin Schrepp, Andreas Hinderks και Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'el', 'b74b10187c47ba41', 'Πηγή: το εγχειρίδιο του UEQ, η επίσημη λίστα των στοιχείων του UEQ-S σε κάθε γλώσσα και το επίσημο φύλλο ανάλυσης του UEQ-S, στο'),
  (gen_random_uuid()::text, 'el', '11277cef9cd51029', 'Μέθοδος: UEQ-S, η σύντομη έκδοση του User Experience Questionnaire (Schrepp, Hinderks και Thomaschewski, 2017). Benchmark και υπολογισμός από το επίσημο φύλλο ανάλυσης του UEQ-S, στο'),
  (gen_random_uuid()::text, 'el', '9c0dcc2a186d213d', 'Μέθοδος: User Experience Questionnaire (Laugwitz, Held και Schrepp, 2008). Benchmark των Schrepp, Hinderks και Thomaschewski (2017) και υπολογισμός από το επίσημο φύλλο ανάλυσης, στο'),
  (gen_random_uuid()::text, 'el', 'b391ed244a83d62b', 'Το UEQ και το UEQ-S είναι δωρεάν και τα συντηρούν οι συγγραφείς στον επίσημο ιστότοπο'),
  (gen_random_uuid()::text, 'tr', 'f94716968ee98017', '. Oradan gelenler: 37 dilde anketler, el kitabı, benchmark ve aracın kullandığı ve dışa aktardığı, Martin Schrepp''in resmî analiz tabloları. Ferramenta UEQ resmî bir UEQ ürünü değildir ve yazarlarla bağlantısı yoktur.'),
  (gen_random_uuid()::text, 'tr', '6560c2d946651623', '. UEQ-S, Martin Schrepp, Andreas Hinderks ve Jörg Thomaschewski''ye aittir (2017).'),
  (gen_random_uuid()::text, 'tr', 'b74b10187c47ba41', 'Kaynak: UEQ el kitabı, her dilde UEQ-S maddelerinin resmî listesi ve UEQ-S''nin resmî analiz tablosu,'),
  (gen_random_uuid()::text, 'tr', '11277cef9cd51029', 'Yöntem: UEQ-S, User Experience Questionnaire''in kısa sürümü (Schrepp, Hinderks ve Thomaschewski, 2017). Benchmark ve hesaplama UEQ-S''nin resmî analiz tablosundan,'),
  (gen_random_uuid()::text, 'tr', '9c0dcc2a186d213d', 'Yöntem: User Experience Questionnaire (Laugwitz, Held ve Schrepp, 2008). Benchmark: Schrepp, Hinderks ve Thomaschewski (2017); hesaplama resmî analiz tablosundan,'),
  (gen_random_uuid()::text, 'tr', 'b391ed244a83d62b', 'UEQ ve UEQ-S ücretsizdir ve yazarları tarafından resmî sitede güncel tutulur:'),
  (gen_random_uuid()::text, 'ar', 'f94716968ee98017', '. ومن هناك تأتي الاستبيانات بـ 37 لغة، والدليل، والمقارنة المرجعية، وأوراق التحليل الرسمية لمارتن شريب (Martin Schrepp)، التي تستخدمها الأداة وتصدّرها. Ferramenta UEQ ليست منتجًا رسميًا لـ UEQ ولا صلة لها بالمؤلفين.'),
  (gen_random_uuid()::text, 'ar', '6560c2d946651623', '. UEQ-S من إعداد Martin Schrepp وAndreas Hinderks وJörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'ar', 'b74b10187c47ba41', 'المصدر: دليل UEQ، والقائمة الرسمية لبنود UEQ-S بكل لغة، وورقة التحليل الرسمية لـ UEQ-S، على'),
  (gen_random_uuid()::text, 'ar', '11277cef9cd51029', 'المنهج: UEQ-S، النسخة القصيرة من User Experience Questionnaire (Schrepp وHinderks وThomaschewski، 2017). المقارنة المرجعية والحساب من ورقة التحليل الرسمية لـ UEQ-S، على'),
  (gen_random_uuid()::text, 'ar', '9c0dcc2a186d213d', 'المنهج: User Experience Questionnaire (Laugwitz وHeld وSchrepp، 2008). المقارنة المرجعية لـ Schrepp وHinderks وThomaschewski (2017) والحساب من ورقة التحليل الرسمية، على'),
  (gen_random_uuid()::text, 'ar', 'b391ed244a83d62b', 'UEQ وUEQ-S مجانيان ويحافظ عليهما المؤلفون على الموقع الرسمي'),
  (gen_random_uuid()::text, 'he', 'f94716968ee98017', '. משם מגיעים השאלונים ב-37 שפות, המדריך, ה-benchmark וגיליונות הניתוח הרשמיים של Martin Schrepp, שהכלי משתמש בהם ומייצא אותם. Ferramenta UEQ אינו מוצר רשמי של UEQ ואין לו קשר למחברים.'),
  (gen_random_uuid()::text, 'he', '6560c2d946651623', '. ה-UEQ-S הוא של Martin Schrepp, Andreas Hinderks ו-Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'he', 'b74b10187c47ba41', 'מקור: המדריך של UEQ, הרשימה הרשמית של פריטי UEQ-S בכל שפה וגיליון הניתוח הרשמי של UEQ-S, באתר'),
  (gen_random_uuid()::text, 'he', '11277cef9cd51029', 'שיטה: UEQ-S, הגרסה הקצרה של User Experience Questionnaire (Schrepp, Hinderks ו-Thomaschewski, 2017). benchmark וחישוב מגיליון הניתוח הרשמי של UEQ-S, באתר'),
  (gen_random_uuid()::text, 'he', '9c0dcc2a186d213d', 'שיטה: User Experience Questionnaire (Laugwitz, Held ו-Schrepp, 2008). benchmark של Schrepp, Hinderks ו-Thomaschewski (2017) וחישוב מגיליון הניתוח הרשמי, באתר'),
  (gen_random_uuid()::text, 'he', 'b391ed244a83d62b', 'UEQ ו-UEQ-S חינמיים, והמחברים מתחזקים אותם באתר הרשמי'),
  (gen_random_uuid()::text, 'fa', 'f94716968ee98017', '. پرسش‌نامه‌ها به ۳۷ زبان، راهنما، بنچمارک و صفحه‌گسترده‌های رسمی تحلیل Martin Schrepp که این ابزار از آن‌ها استفاده می‌کند و خروجی می‌گیرد، از همان‌جا آمده‌اند. Ferramenta UEQ محصول رسمی UEQ نیست و با نویسندگان ارتباطی ندارد.'),
  (gen_random_uuid()::text, 'fa', '6560c2d946651623', '. UEQ-S اثر Martin Schrepp، Andreas Hinderks و Jörg Thomaschewski است (۲۰۱۷).'),
  (gen_random_uuid()::text, 'fa', 'b74b10187c47ba41', 'منبع: راهنمای UEQ، فهرست رسمی گویه‌های UEQ-S در هر زبان و صفحه‌گستردهٔ رسمی تحلیل UEQ-S، در'),
  (gen_random_uuid()::text, 'fa', '11277cef9cd51029', 'روش: UEQ-S، نسخهٔ کوتاه User Experience Questionnaire (Schrepp، Hinderks و Thomaschewski، ۲۰۱۷). بنچمارک و محاسبه از صفحه‌گستردهٔ رسمی تحلیل UEQ-S، در'),
  (gen_random_uuid()::text, 'fa', '9c0dcc2a186d213d', 'روش: User Experience Questionnaire (Laugwitz، Held و Schrepp، ۲۰۰۸). بنچمارک Schrepp، Hinderks و Thomaschewski (۲۰۱۷) و محاسبه از صفحه‌گستردهٔ رسمی تحلیل، در'),
  (gen_random_uuid()::text, 'fa', 'b391ed244a83d62b', 'UEQ و UEQ-S رایگان‌اند و نویسندگان آن‌ها را در وب‌سایت رسمی نگهداری می‌کنند'),
  (gen_random_uuid()::text, 'hi', 'f94716968ee98017', '. वहीं से 37 भाषाओं में प्रश्नावलियाँ, हैंडबुक, बेंचमार्क और Martin Schrepp की आधिकारिक विश्लेषण स्प्रेडशीट आती हैं, जिन्हें यह टूल उपयोग और निर्यात करता है। Ferramenta UEQ, UEQ का आधिकारिक उत्पाद नहीं है और इसका लेखकों से कोई संबंध नहीं है।'),
  (gen_random_uuid()::text, 'hi', '6560c2d946651623', '. UEQ-S, Martin Schrepp, Andreas Hinderks और Jörg Thomaschewski (2017) का है।'),
  (gen_random_uuid()::text, 'hi', 'b74b10187c47ba41', 'स्रोत: UEQ हैंडबुक, हर भाषा में UEQ-S मदों की आधिकारिक सूची और UEQ-S की आधिकारिक विश्लेषण स्प्रेडशीट, यहाँ:'),
  (gen_random_uuid()::text, 'hi', '11277cef9cd51029', 'पद्धति: UEQ-S, User Experience Questionnaire का छोटा संस्करण (Schrepp, Hinderks और Thomaschewski, 2017)। बेंचमार्क और गणना UEQ-S की आधिकारिक विश्लेषण स्प्रेडशीट से, यहाँ:'),
  (gen_random_uuid()::text, 'hi', '9c0dcc2a186d213d', 'पद्धति: User Experience Questionnaire (Laugwitz, Held और Schrepp, 2008)। बेंचमार्क Schrepp, Hinderks और Thomaschewski (2017) का और गणना आधिकारिक विश्लेषण स्प्रेडशीट से, यहाँ:'),
  (gen_random_uuid()::text, 'hi', 'b391ed244a83d62b', 'UEQ और UEQ-S निःशुल्क हैं और लेखक इन्हें आधिकारिक वेबसाइट पर बनाए रखते हैं:'),
  (gen_random_uuid()::text, 'mr', 'f94716968ee98017', '. तेथूनच 37 भाषांतील प्रश्नावली, हँडबुक, बेंचमार्क आणि Martin Schrepp यांच्या अधिकृत विश्लेषण स्प्रेडशीट येतात, ज्या हे साधन वापरते आणि निर्यात करते. Ferramenta UEQ हे UEQ चे अधिकृत उत्पादन नाही आणि त्याचा लेखकांशी संबंध नाही.'),
  (gen_random_uuid()::text, 'mr', '6560c2d946651623', '. UEQ-S चे लेखक Martin Schrepp, Andreas Hinderks आणि Jörg Thomaschewski (2017) आहेत.'),
  (gen_random_uuid()::text, 'mr', 'b74b10187c47ba41', 'स्रोत: UEQ हँडबुक, प्रत्येक भाषेतील UEQ-S घटकांची अधिकृत यादी आणि UEQ-S ची अधिकृत विश्लेषण स्प्रेडशीट, येथे:'),
  (gen_random_uuid()::text, 'mr', '11277cef9cd51029', 'पद्धत: UEQ-S, User Experience Questionnaire ची लहान आवृत्ती (Schrepp, Hinderks आणि Thomaschewski, 2017). बेंचमार्क आणि गणना UEQ-S च्या अधिकृत विश्लेषण स्प्रेडशीटमधून, येथे:'),
  (gen_random_uuid()::text, 'mr', '9c0dcc2a186d213d', 'पद्धत: User Experience Questionnaire (Laugwitz, Held आणि Schrepp, 2008). बेंचमार्क Schrepp, Hinderks आणि Thomaschewski (2017) यांचा आणि गणना अधिकृत विश्लेषण स्प्रेडशीटमधून, येथे:'),
  (gen_random_uuid()::text, 'mr', 'b391ed244a83d62b', 'UEQ आणि UEQ-S विनामूल्य आहेत आणि लेखक त्यांची देखभाल अधिकृत संकेतस्थळावर करतात:'),
  (gen_random_uuid()::text, 'bn', 'f94716968ee98017', '. সেখান থেকেই আসে ৩৭টি ভাষার প্রশ্নাবলি, হ্যান্ডবুক, বেঞ্চমার্ক এবং Martin Schrepp-এর অফিসিয়াল বিশ্লেষণ স্প্রেডশিট, যেগুলো এই টুল ব্যবহার ও রপ্তানি করে। Ferramenta UEQ কোনো অফিসিয়াল UEQ পণ্য নয় এবং লেখকদের সঙ্গে এর কোনো সম্পর্ক নেই।'),
  (gen_random_uuid()::text, 'bn', '6560c2d946651623', '. UEQ-S তৈরি করেছেন Martin Schrepp, Andreas Hinderks ও Jörg Thomaschewski (২০১৭)।'),
  (gen_random_uuid()::text, 'bn', 'b74b10187c47ba41', 'সূত্র: UEQ হ্যান্ডবুক, প্রতিটি ভাষায় UEQ-S আইটেমের অফিসিয়াল তালিকা এবং UEQ-S-এর অফিসিয়াল বিশ্লেষণ স্প্রেডশিট, এখানে:'),
  (gen_random_uuid()::text, 'bn', '11277cef9cd51029', 'পদ্ধতি: UEQ-S, User Experience Questionnaire-এর সংক্ষিপ্ত সংস্করণ (Schrepp, Hinderks ও Thomaschewski, ২০১৭)। বেঞ্চমার্ক ও হিসাব UEQ-S-এর অফিসিয়াল বিশ্লেষণ স্প্রেডশিট থেকে, এখানে:'),
  (gen_random_uuid()::text, 'bn', '9c0dcc2a186d213d', 'পদ্ধতি: User Experience Questionnaire (Laugwitz, Held ও Schrepp, ২০০৮)। বেঞ্চমার্ক Schrepp, Hinderks ও Thomaschewski (২০১৭)-এর এবং হিসাব অফিসিয়াল বিশ্লেষণ স্প্রেডশিট থেকে, এখানে:'),
  (gen_random_uuid()::text, 'bn', 'b391ed244a83d62b', 'UEQ ও UEQ-S বিনামূল্যে পাওয়া যায় এবং লেখকেরা অফিসিয়াল ওয়েবসাইটে এগুলো হালনাগাদ রাখেন:'),
  (gen_random_uuid()::text, 'ta', 'f94716968ee98017', '. அங்கிருந்துதான் 37 மொழிகளில் கேள்வித்தாள்கள், கையேடு, பெஞ்ச்மார்க் மற்றும் Martin Schrepp உருவாக்கிய அதிகாரப்பூர்வ பகுப்பாய்வு விரிதாள்கள் வருகின்றன; இந்தக் கருவி அவற்றைப் பயன்படுத்தி ஏற்றுமதி செய்கிறது. Ferramenta UEQ என்பது UEQ-இன் அதிகாரப்பூர்வ தயாரிப்பு அல்ல; ஆசிரியர்களுடன் இதற்குத் தொடர்பு இல்லை.'),
  (gen_random_uuid()::text, 'ta', '6560c2d946651623', '. UEQ-S-ஐ உருவாக்கியவர்கள் Martin Schrepp, Andreas Hinderks, Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'ta', 'b74b10187c47ba41', 'மூலம்: UEQ கையேடு, ஒவ்வொரு மொழியிலும் UEQ-S உருப்படிகளின் அதிகாரப்பூர்வ பட்டியல், UEQ-S அதிகாரப்பூர்வ பகுப்பாய்வு விரிதாள், இங்கே:'),
  (gen_random_uuid()::text, 'ta', '11277cef9cd51029', 'முறை: UEQ-S, User Experience Questionnaire-இன் குறுகிய பதிப்பு (Schrepp, Hinderks, Thomaschewski, 2017). பெஞ்ச்மார்க்கும் கணக்கீடும் UEQ-S அதிகாரப்பூர்வ பகுப்பாய்வு விரிதாளிலிருந்து, இங்கே:'),
  (gen_random_uuid()::text, 'ta', '9c0dcc2a186d213d', 'முறை: User Experience Questionnaire (Laugwitz, Held, Schrepp, 2008). பெஞ்ச்மார்க் Schrepp, Hinderks, Thomaschewski (2017); கணக்கீடு அதிகாரப்பூர்வ பகுப்பாய்வு விரிதாளிலிருந்து, இங்கே:'),
  (gen_random_uuid()::text, 'ta', 'b391ed244a83d62b', 'UEQ-உம் UEQ-S-உம் இலவசம்; ஆசிரியர்கள் அவற்றை அதிகாரப்பூர்வ இணையதளத்தில் பராமரிக்கிறார்கள்:'),
  (gen_random_uuid()::text, 'kn', 'f94716968ee98017', '. ಅಲ್ಲಿಂದಲೇ 37 ಭಾಷೆಗಳ ಪ್ರಶ್ನಾವಳಿಗಳು, ಕೈಪಿಡಿ, ಬೆಂಚ್‌ಮಾರ್ಕ್ ಮತ್ತು Martin Schrepp ಅವರ ಅಧಿಕೃತ ವಿಶ್ಲೇಷಣಾ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್‌ಗಳು ಬರುತ್ತವೆ; ಈ ಸಾಧನ ಅವುಗಳನ್ನು ಬಳಸುತ್ತದೆ ಮತ್ತು ರಫ್ತು ಮಾಡುತ್ತದೆ. Ferramenta UEQ ಎಂಬುದು UEQ ನ ಅಧಿಕೃತ ಉತ್ಪನ್ನವಲ್ಲ ಮತ್ತು ಲೇಖಕರೊಂದಿಗೆ ಇದಕ್ಕೆ ಸಂಬಂಧವಿಲ್ಲ.'),
  (gen_random_uuid()::text, 'kn', '6560c2d946651623', '. UEQ-S ಅನ್ನು Martin Schrepp, Andreas Hinderks ಮತ್ತು Jörg Thomaschewski (2017) ರೂಪಿಸಿದ್ದಾರೆ.'),
  (gen_random_uuid()::text, 'kn', 'b74b10187c47ba41', 'ಮೂಲ: UEQ ಕೈಪಿಡಿ, ಪ್ರತಿ ಭಾಷೆಯಲ್ಲಿ UEQ-S ಅಂಶಗಳ ಅಧಿಕೃತ ಪಟ್ಟಿ ಮತ್ತು UEQ-S ನ ಅಧಿಕೃತ ವಿಶ್ಲೇಷಣಾ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್, ಇಲ್ಲಿ:'),
  (gen_random_uuid()::text, 'kn', '11277cef9cd51029', 'ವಿಧಾನ: UEQ-S, User Experience Questionnaire ನ ಚಿಕ್ಕ ಆವೃತ್ತಿ (Schrepp, Hinderks ಮತ್ತು Thomaschewski, 2017). ಬೆಂಚ್‌ಮಾರ್ಕ್ ಮತ್ತು ಲೆಕ್ಕಾಚಾರ UEQ-S ನ ಅಧಿಕೃತ ವಿಶ್ಲೇಷಣಾ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್‌ನಿಂದ, ಇಲ್ಲಿ:'),
  (gen_random_uuid()::text, 'kn', '9c0dcc2a186d213d', 'ವಿಧಾನ: User Experience Questionnaire (Laugwitz, Held ಮತ್ತು Schrepp, 2008). ಬೆಂಚ್‌ಮಾರ್ಕ್ Schrepp, Hinderks ಮತ್ತು Thomaschewski (2017) ಅವರದು; ಲೆಕ್ಕಾಚಾರ ಅಧಿಕೃತ ವಿಶ್ಲೇಷಣಾ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್‌ನಿಂದ, ಇಲ್ಲಿ:'),
  (gen_random_uuid()::text, 'kn', 'b391ed244a83d62b', 'UEQ ಮತ್ತು UEQ-S ಉಚಿತ; ಲೇಖಕರು ಅವುಗಳನ್ನು ಅಧಿಕೃತ ಜಾಲತಾಣದಲ್ಲಿ ನಿರ್ವಹಿಸುತ್ತಾರೆ:'),
  (gen_random_uuid()::text, 'th', 'f94716968ee98017', ' จากที่นั่นมีแบบสอบถาม 37 ภาษา คู่มือ benchmark และสเปรดชีตวิเคราะห์ทางการของ Martin Schrepp ที่เครื่องมือนี้ใช้และส่งออก Ferramenta UEQ ไม่ใช่ผลิตภัณฑ์ทางการของ UEQ และไม่มีความเกี่ยวข้องกับผู้สร้าง'),
  (gen_random_uuid()::text, 'th', '6560c2d946651623', ' UEQ-S เป็นผลงานของ Martin Schrepp, Andreas Hinderks และ Jörg Thomaschewski (2017)'),
  (gen_random_uuid()::text, 'th', 'b74b10187c47ba41', 'แหล่งที่มา: คู่มือ UEQ รายการข้อคำถามทางการของ UEQ-S ในแต่ละภาษา และสเปรดชีตวิเคราะห์ทางการของ UEQ-S ที่'),
  (gen_random_uuid()::text, 'th', '11277cef9cd51029', 'วิธีการ: UEQ-S ฉบับสั้นของ User Experience Questionnaire (Schrepp, Hinderks และ Thomaschewski, 2017) benchmark และการคำนวณจากสเปรดชีตวิเคราะห์ทางการของ UEQ-S ที่'),
  (gen_random_uuid()::text, 'th', '9c0dcc2a186d213d', 'วิธีการ: User Experience Questionnaire (Laugwitz, Held และ Schrepp, 2008) benchmark ของ Schrepp, Hinderks และ Thomaschewski (2017) และการคำนวณจากสเปรดชีตวิเคราะห์ทางการ ที่'),
  (gen_random_uuid()::text, 'th', 'b391ed244a83d62b', 'UEQ และ UEQ-S ใช้ได้ฟรี และผู้สร้างดูแลไว้ที่เว็บไซต์ทางการ'),
  (gen_random_uuid()::text, 'ms', 'f94716968ee98017', '. Dari situlah datangnya soal selidik dalam 37 bahasa, buku panduan, penanda aras dan hamparan analisis rasmi oleh Martin Schrepp yang digunakan dan dieksport oleh alat ini. Ferramenta UEQ bukan produk rasmi UEQ dan tidak mempunyai kaitan dengan pengarang.'),
  (gen_random_uuid()::text, 'ms', '6560c2d946651623', '. UEQ-S ialah hasil Martin Schrepp, Andreas Hinderks dan Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'ms', 'b74b10187c47ba41', 'Sumber: buku panduan UEQ, senarai rasmi item UEQ-S dalam setiap bahasa dan hamparan analisis rasmi UEQ-S, di'),
  (gen_random_uuid()::text, 'ms', '11277cef9cd51029', 'Kaedah: UEQ-S, versi pendek User Experience Questionnaire (Schrepp, Hinderks dan Thomaschewski, 2017). Penanda aras dan pengiraan daripada hamparan analisis rasmi UEQ-S, di'),
  (gen_random_uuid()::text, 'ms', '9c0dcc2a186d213d', 'Kaedah: User Experience Questionnaire (Laugwitz, Held dan Schrepp, 2008). Penanda aras oleh Schrepp, Hinderks dan Thomaschewski (2017) dan pengiraan daripada hamparan analisis rasmi, di'),
  (gen_random_uuid()::text, 'ms', 'b391ed244a83d62b', 'UEQ dan UEQ-S adalah percuma dan diselenggara oleh pengarang di laman web rasmi'),
  (gen_random_uuid()::text, 'id', 'f94716968ee98017', '. Dari sana berasal kuesioner dalam 37 bahasa, buku panduan, tolok ukur, dan lembar kerja analisis resmi karya Martin Schrepp yang dipakai dan diekspor oleh alat ini. Ferramenta UEQ bukan produk resmi UEQ dan tidak berafiliasi dengan para penulis.'),
  (gen_random_uuid()::text, 'id', '6560c2d946651623', '. UEQ-S adalah karya Martin Schrepp, Andreas Hinderks, dan Jörg Thomaschewski (2017).'),
  (gen_random_uuid()::text, 'id', 'b74b10187c47ba41', 'Sumber: buku panduan UEQ, daftar resmi butir UEQ-S di setiap bahasa, dan lembar kerja analisis resmi UEQ-S, di'),
  (gen_random_uuid()::text, 'id', '11277cef9cd51029', 'Metode: UEQ-S, versi pendek User Experience Questionnaire (Schrepp, Hinderks, dan Thomaschewski, 2017). Tolok ukur dan perhitungan dari lembar kerja analisis resmi UEQ-S, di'),
  (gen_random_uuid()::text, 'id', '9c0dcc2a186d213d', 'Metode: User Experience Questionnaire (Laugwitz, Held, dan Schrepp, 2008). Tolok ukur dari Schrepp, Hinderks, dan Thomaschewski (2017) serta perhitungan dari lembar kerja analisis resmi, di'),
  (gen_random_uuid()::text, 'id', 'b391ed244a83d62b', 'UEQ dan UEQ-S gratis dan dikelola para penulisnya di situs resmi'),
  (gen_random_uuid()::text, 'zh', 'f94716968ee98017', '。37 种语言的问卷、手册、基准以及 Martin Schrepp 制作的官方分析表格都来自那里，本工具使用并导出这些材料。Ferramenta UEQ 不是 UEQ 的官方产品，与作者没有关联。'),
  (gen_random_uuid()::text, 'zh', '6560c2d946651623', '。UEQ-S 由 Martin Schrepp、Andreas Hinderks 和 Jörg Thomaschewski 编制（2017）。'),
  (gen_random_uuid()::text, 'zh', 'b74b10187c47ba41', '来源：UEQ 手册、各语言 UEQ-S 条目的官方列表和 UEQ-S 官方分析表格，见'),
  (gen_random_uuid()::text, 'zh', '11277cef9cd51029', '方法：UEQ-S，User Experience Questionnaire 的简版（Schrepp、Hinderks 和 Thomaschewski，2017）。基准和计算来自 UEQ-S 官方分析表格，见'),
  (gen_random_uuid()::text, 'zh', '9c0dcc2a186d213d', '方法：User Experience Questionnaire（Laugwitz、Held 和 Schrepp，2008）。基准来自 Schrepp、Hinderks 和 Thomaschewski（2017），计算来自官方分析表格，见'),
  (gen_random_uuid()::text, 'zh', 'b391ed244a83d62b', 'UEQ 和 UEQ-S 免费使用，由作者在官方网站上维护：'),
  (gen_random_uuid()::text, 'ja', 'f94716968ee98017', '。37 言語の質問票、ハンドブック、ベンチマーク、そして Martin Schrepp による公式分析シートはそこで公開されており、このツールはそれらを使用・エクスポートしています。Ferramenta UEQ は UEQ の公式製品ではなく、著者とは関係ありません。'),
  (gen_random_uuid()::text, 'ja', '6560c2d946651623', '。UEQ-S は Martin Schrepp、Andreas Hinderks、Jörg Thomaschewski によるものです（2017）。'),
  (gen_random_uuid()::text, 'ja', 'b74b10187c47ba41', '出典：UEQ ハンドブック、各言語の UEQ-S 項目の公式リスト、UEQ-S 公式分析シート。掲載先：'),
  (gen_random_uuid()::text, 'ja', '11277cef9cd51029', '方法：UEQ-S（User Experience Questionnaire の短縮版、Schrepp・Hinderks・Thomaschewski、2017）。ベンチマークと計算は UEQ-S 公式分析シートによる。掲載先：'),
  (gen_random_uuid()::text, 'ja', '9c0dcc2a186d213d', '方法：User Experience Questionnaire（Laugwitz・Held・Schrepp、2008）。ベンチマークは Schrepp・Hinderks・Thomaschewski（2017）、計算は公式分析シートによる。掲載先：'),
  (gen_random_uuid()::text, 'ja', 'b391ed244a83d62b', 'UEQ と UEQ-S は無料で、著者が公式サイトで管理しています：'),
  (gen_random_uuid()::text, 'ko', 'f94716968ee98017', '. 37개 언어의 설문지, 핸드북, 벤치마크, 그리고 Martin Schrepp의 공식 분석 시트가 모두 그곳에서 제공되며, 이 도구는 이를 사용하고 내보냅니다. Ferramenta UEQ는 UEQ의 공식 제품이 아니며 저자들과 관련이 없습니다.'),
  (gen_random_uuid()::text, 'ko', '6560c2d946651623', '. UEQ-S는 Martin Schrepp, Andreas Hinderks, Jörg Thomaschewski의 작업입니다(2017).'),
  (gen_random_uuid()::text, 'ko', 'b74b10187c47ba41', '출처: UEQ 핸드북, 언어별 UEQ-S 문항 공식 목록, UEQ-S 공식 분석 시트, 사이트:'),
  (gen_random_uuid()::text, 'ko', '11277cef9cd51029', '방법: UEQ-S, User Experience Questionnaire의 단축판(Schrepp, Hinderks, Thomaschewski, 2017). 벤치마크와 계산은 UEQ-S 공식 분석 시트 기준, 사이트:'),
  (gen_random_uuid()::text, 'ko', '9c0dcc2a186d213d', '방법: User Experience Questionnaire(Laugwitz, Held, Schrepp, 2008). 벤치마크는 Schrepp, Hinderks, Thomaschewski(2017), 계산은 공식 분석 시트 기준, 사이트:'),
  (gen_random_uuid()::text, 'ko', 'b391ed244a83d62b', 'UEQ와 UEQ-S는 무료이며 저자들이 공식 웹사이트에서 관리합니다:')
